using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

namespace McpServer;

// MCP SDK discovers tools by scanning for [McpServerToolType] classes.
// Each public method marked [McpServerTool] becomes a callable tool.
// Constructor parameters are resolved from DI automatically.
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _http;

    // The SDK resolves this via DI — register IHttpClientFactory or a named HttpClient.
    public WeatherTools(HttpClient http)
    {
        _http = http;
    }

    [McpServerTool, Description("Get current weather for a city using the Open-Meteo API.")]
    public async Task<string> GetWeather(
        [Description("City latitude")] double latitude,
        [Description("City longitude")] double longitude)
    {
        var url = $"https://api.open-meteo.com/v1/forecast"
                + $"?latitude={latitude}&longitude={longitude}"
                + $"&current=temperature_2m,wind_speed_10m";

        var response = await _http.GetFromJsonAsync<WeatherResponse>(url);
        if (response?.Current is null)
            return "Unable to fetch weather data.";

        var c = response.Current;
        return $"Temperature: {c.Temperature}°C, Wind: {c.WindSpeed} km/h";
    }

    [McpServerTool, Description("Look up coordinates for a city name using Open-Meteo geocoding.")]
    public async Task<string> GeolocateCity(
        [Description("City name to search for")] string city)
    {
        var url = $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(city)}&count=1";

        var response = await _http.GetFromJsonAsync<GeoResponse>(url);
        if (response?.Results is not { Count: > 0 })
            return $"City '{city}' not found.";

        var r = response.Results[0];
        return $"{r.Name} ({r.Country}): lat={r.Latitude}, lon={r.Longitude}";
    }
}

// DTOs for Open-Meteo responses
public record WeatherResponse(
    [property: JsonPropertyName("current")] CurrentWeather? Current);

public record CurrentWeather(
    [property: JsonPropertyName("temperature_2m")] double Temperature,
    [property: JsonPropertyName("wind_speed_10m")] double WindSpeed);

public record GeoResponse(
    [property: JsonPropertyName("results")] List<GeoResult>? Results);

public record GeoResult(
    [property: JsonPropertyName("name")] string Name,
    [property: JsonPropertyName("country")] string Country,
    [property: JsonPropertyName("latitude")] double Latitude,
    [property: JsonPropertyName("longitude")] double Longitude);

